	[220316] = {
		id = 220316,
		skillName = '玛夏多召唤',
		describe = '月相轮回：#L0#月相按照【新月】、【上弦】、【满月】、【下弦】的顺序轮回变化，每次大回合开始时和自身行动回合开始时，月相往后变化一次\n#F10#\n#F40#【新月】：开始时使敌方随机3个目标立刻失去100点怒气，持续期间给己方所有超、鬼系精灵提升50%伤害减免，之后每次月相变化，会将8%的伤害减免转化为20%伤害加成，周而复始,【上弦】：开始时自身立刻获得150点怒气，对己方其他随机鬼系精灵添加【月隐】1回合，重复添加【月隐】时改为提升目标40%最终伤害减免2回合;对敌方随机单位添加【孤月】1回合,【满月】：开始时落下6道【月华】，攻击敌方随机单位（单挑玩法中同一大回合内每个单位最多受到2次月华伤害），每道造成15%露奈雅拉生命上限的#C0xF13B54#特殊伤害#C0x5B545B#（不超过500%特攻），每次触发满月月相的效果后，【月华】伤害永久提升25%（最多150%）,【下弦】：持续期间己方鬼系精灵进入【隐身】状态，超系精灵提升15%速度,#L10#轮回复生：#L0#一轮月相轮回后，自身获得【月轮印记】;自身受到致命伤害时，有100%概率消耗【月轮印记】并在下个大回合的自身行动回合开始时满血满怒复活，复活后月相重新开始轮回，每次复活后，下次复活概率减半（全场最多复活三次）\n#F10#\n#F40#【月轮印记】：不可叠加，获得时为己方全体超、鬼系精灵治疗露奈雅拉25%生命上限的生命，并使鬼系队友获得20%增伤,#L10#幻影防守（光环）：#L0#己方处于【不可视】状态下的精灵，无法被链接，获得#C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#附加伤害/被动伤害减免（对鬼系精灵效果翻倍），且所造成的伤害不会解除睡眠类效果;己方鬼系精灵处于【不可视】状态下时，每次攻击敌人时令目标增长50点怒气上限（露奈雅拉触发时效果翻倍），怒气上限提升效果持续至目标下一次必杀技结束（最多提升300点怒气上限），攻击怒气上限高于自身的单位时，伤害增加20%，\n#F10#\n#F40#【不可视】：包括月隐、隐身等效果，详情参见战斗手册对应条目',
		describe1 = __data_t__describe1[220316],
		-- {'月相轮回：#L0#月相按照【新月】、【上弦】、【满月】、【下弦】的顺序轮回变化，每次大回合开始时和自身行动回合开始时，月相往后变化一次\n#F10#\n#F40#【新月】：开始时使敌方随机3个目标立刻失去100点怒气，持续期间给己方所有超、鬼系精灵提升50%伤害减免，之后每次月相变化，会将8%的伤害减免转化为20%伤害加成，周而复始,【上弦】：开始时自身立刻获得150点怒气，对己方其他随机鬼系精灵添加【月隐】1回合，重复添加【月隐】时改为提升目标40%最终伤害减免2回合', '对敌方随机单位添加【孤月】1回合,【满月】：开始时落下6道【月华】，攻击敌方随机单位（单挑玩法中同一大回合内每个单位最多受到2次月华伤害），每道造成15%露奈雅拉生命上限的#C0xF13B54#特殊伤害#C0x5B545B#（不超过500%特攻），每次触发满月月相的效果后，【月华】伤害永久提升25%（最多150%）,【下弦】：持续期间己方鬼系精灵进入【隐身】状态，超系精灵提升15%速度,#L10#轮回复生：#L0#一轮月相轮回后，自身获得【月轮印记】', '自身受到致命伤害时，有100%概率消耗【月轮印记】并在下个大回合的自身行动回合开始时满血满怒复活，复活后月相重新开始轮回，每次复活后，下次复活概率减半（全场最多复活三次）\n#F10#\n#F40#【月轮印记】：不可叠加，获得时为己方全体超、鬼系精灵治疗露奈雅拉25%生命上限的生命，并使鬼系队友获得20%增伤,#L10#幻影防守（光环）：#L0#己方处于【不可视】状态下的精灵，无法被链接，获得#C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#附加伤害/被动伤害减免（对鬼系精灵效果翻倍），且所造成的伤害不会解除睡眠类效果', '己方鬼系精灵处于【不可视】状态下时，每次攻击敌人时令目标增长50点怒气上限（露奈雅拉触发时效果翻倍），怒气上限提升效果持续至目标下一次必杀技结束（最多提升300点怒气上限），攻击怒气上限高于自身的单位时，伤害增加20%，\n#F10#\n#F40#【不可视】：包括月隐、隐身等效果，详情参见战斗手册对应条目'}
		starEffect = __data_t__starEffect[220316],
		-- {8}
		zawakeEffect = __data_t__zawakeEffect[220316],
		-- {79004, 1}
		zawakeSimpleDesc = '每次己方单位入场时若己方存在3个及以上鬼系精灵，使自身和其他3个攻击最高的鬼系精灵获得【月隐】效果1回合；自身处在【不可视】状态下时，己方全体鬼系精灵获得20%最终伤害减免；经历一轮月相轮回后，己方鬼系永久保留25%月相轮回期间获得的伤害加成（最高保留100%）',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
